import { expect, test } from '../../fixtures/billing';
import { PERIOD_END, projects } from '../../fixtures/testData';

test('BR-04 each converted line is rounded half away from zero in the invoice currency before tax, and the totals add up the rounded lines @critical', async ({ proposal, page }) => {
  await proposal.create(projects.polarReporting, PERIOD_END);

  // 2.10 h at 120.00 EUR plus 18.00 EUR is 270.00 EUR, and 270.00 x 1.0835 = 292.545 USD exactly.
  // Rounded half away from zero, that line is 292.55. Rounding only the total, half to even, gave a subtotal of 2,632.90.
  await proposal.adjust(3, '18', 'Extra report review agreed with customer');

  await expect(page.locator('#proposal-currency')).toHaveText('USD');
  await expect(page.locator('#proposal-rate')).toHaveText('1.0835');
  await expect(proposal.lines).toHaveCount(3);
  await expect(proposal.line(3)).toContainText('2026-10-14');
  await expect(proposal.line(3).locator('.line-adjustment')).toHaveText('+18.00');
  await expect(proposal.amountOf(1)).toHaveText('1,300.20');
  await expect(proposal.amountOf(2)).toHaveText('1,040.16');
  await expect(proposal.amountOf(3)).toHaveText('292.55');
  await expect(proposal.line(3).locator('.line-tax')).toHaveText('74.60');
  await expect(proposal.subtotal).toHaveText('2,632.91');
  await expect(proposal.tax).toHaveText('671.39');
  await expect(proposal.total).toHaveText('3,304.30 USD');

  page.once('dialog', (dialog) => dialog.accept());
  await page.locator('#delete-proposal').click();
  await expect(page.getByRole('status')).toHaveText('Proposal deleted.');
});
